import{_ as e,I as a,g as r,j as l}from"./chunks/framework.Ha9mtr6N.js";const h=JSON.parse('{"title":"Аналитика и графики","description":"Приборная панель собственника: KPI, точка безубыточности, окупаемость времени (Time ROI) и финансовые тренды.","frontmatter":{"title":"Аналитика и графики","description":"Приборная панель собственника: KPI, точка безубыточности, окупаемость времени (Time ROI) и финансовые тренды.","order":12},"headers":[],"relativePath":"ru/docs/spaces/production/analytics.md","filePath":"ru/docs/spaces/production/analytics.md"}'),o={name:"ru/docs/spaces/production/analytics.md"};function n(s,t,i,d,g,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="💡-аналитика-приборная-панель-бизнеса" tabindex="-1">💡 Аналитика: Приборная панель бизнеса <a class="header-anchor" href="#💡-аналитика-приборная-панель-бизнеса" aria-label="Permalink to &quot;💡 Аналитика: Приборная панель бизнеса&quot;">​</a></h1><p>Вкладка <strong>«Аналитика»</strong> — это ваш командный центр. Если ДДС показывает, где лежат деньги, а Капитал — сколько стоит бизнес, то Аналитика отвечает на главный вопрос: <strong>«Насколько эффективно работает моя мастерская и в каком направлении она движется?»</strong>.</p><p>Программа автоматически агрегирует данные из всех журналов (продаж, склада, ДДС) и визуализирует их в виде ключевых показателей эффективности (KPI) и интерактивных графиков.</p><hr><h2 id="📊-три-индикатора-здоровья-бизнеса-kpi" tabindex="-1">📊 Три индикатора здоровья бизнеса (KPI) <a class="header-anchor" href="#📊-три-индикатора-здоровья-бизнеса-kpi" aria-label="Permalink to &quot;📊 Три индикатора здоровья бизнеса (KPI)&quot;">​</a></h2><p>В верхней части экрана расположены три карточки с метриками, которые рассчитываются в реальном времени на основе всей истории вашей работы.</p><h3 id="_1-💵-среднии-чек" tabindex="-1">1. 💵 Средний чек <a class="header-anchor" href="#_1-💵-среднии-чек" aria-label="Permalink to &quot;1. 💵 Средний чек&quot;">​</a></h3><p>Показывает, сколько денег в среднем приносит одна проведенная сделка.</p><ul><li><strong>Зачем это нужно:</strong> Эта цифра помогает оценить эффективность вашей ценовой политики и работы с клиентами. Если вы внедрили новую упаковку, добавили сопутствующие товары в ассортимент или просто повысили цены — рост среднего чека наглядно подтвердит, что стратегия работает.</li></ul><h3 id="_2-🎯-точка-безубыточности-break-even-point" tabindex="-1">2. 🎯 Точка безубыточности (Break-Even Point) <a class="header-anchor" href="#_2-🎯-точка-безубыточности-break-even-point" aria-label="Permalink to &quot;2. 🎯 Точка безубыточности (Break-Even Point)&quot;">​</a></h3><p>Одна из самых важных цифр для планирования. Программа анализирует ваши постоянные и переменные расходы за последние 6 месяцев и делит их на среднюю прибыль с одного изделия.</p><ul><li><strong>Как читать:</strong> Цифра показывает <strong>минимальное количество изделий</strong>, которое вам необходимо производить и продавать каждый месяц, чтобы мастерская работала «в ноль» (полностью покрывала все расходы на сырье, аренду, электричество, амортизацию и рекламу).</li><li><strong>Бизнес-применение:</strong> Всё, что продано <em>сверх</em> этого количества, начинает генерировать вашу чистую прибыль.</li></ul><h3 id="_3-⏱️-time-roi-окупаемость-времени" tabindex="-1">3. ⏱️ Time ROI (Окупаемость времени) <a class="header-anchor" href="#_3-⏱️-time-roi-окупаемость-времени" aria-label="Permalink to &quot;3. ⏱️ Time ROI (Окупаемость времени)&quot;">​</a></h3><p>Уникальная метрика ОмниКрафт ЕРП, созданная специально для ремесленников. Она рассчитывается по формуле: $$\\text{Time ROI} = \\frac{\\text{Суммарная чистая прибыль}}{\\text{Суммарные часы работы (по нормам из Калькулятора)}}$$</p><ul><li><strong>Смысл показателя:</strong> Цифра показывает, сколько реальных денег приносит вам <strong>один час</strong> работы за верстаком.</li><li><strong>Как использовать:</strong> Эта метрика безжалостно выявляет «скрытых убийц» вашего времени. Вы можете обнаружить, что сложный рюкзак приносит вам 300 ₽/час из-за огромных трудозатрат, а простой картхолдер — 1 500 ₽/час. Это прямой сигнал к тому, чтобы оптимизировать ассортимент или срочно пересматривать цены на трудоемкие изделия.</li></ul><hr><h2 id="📈-финансовыи-пульс-динамика-за-6-месяцев" tabindex="-1">📈 Финансовый пульс (Динамика за 6 месяцев) <a class="header-anchor" href="#📈-финансовыи-пульс-динамика-за-6-месяцев" aria-label="Permalink to &quot;📈 Финансовый пульс (Динамика за 6 месяцев)&quot;">​</a></h2><p>Линейный график показывает эволюцию вашего бизнеса в разрезе последних полугода. На нем отображаются три ключевые линии:</p><ul><li>🟢 <strong>Выручка:</strong> Объем денег, поступивший от клиентов.</li><li>🟠 <strong>Расходы:</strong> Полная сумма затрат (себестоимость проданных товаров + накладные расходы + операционные траты из ДДС).</li><li>🔵 <strong>Чистая прибыль:</strong> Разница между выручкой и расходами.</li></ul><div class="tip custom-block"><p class="custom-block-title">Как анализировать тренды?</p><p>Обращайте внимание на «ножницы» между линией Выручки и линией Расходов. Если выручка растет, а прибыль падает или стагнирует — это сигнал, что ваша маржинальность снижается (например, из-за подорожания сырья у поставщиков или роста стоимости логистики), и пора закладывать новые цены в Калькулятор.</p></div><hr><h2 id="🥧-структура-выручки-локомотивы-продаж" tabindex="-1">🥧 Структура выручки (Локомотивы продаж) <a class="header-anchor" href="#🥧-структура-выручки-локомотивы-продаж" aria-label="Permalink to &quot;🥧 Структура выручки (Локомотивы продаж)&quot;">​</a></h2><p>Круговая диаграмма наглядно показывает, <strong>какие именно изделия делают вам кассу</strong>. Программа автоматически выделяет Топ-5 самых доходных товаров и группирует остальные в категорию «Прочие».</p><p>Этот график — ваша база для <strong>АВС-анализа</strong> ассортимента:</p><ul><li><strong>Группа А (Лидеры):</strong> Изделия, которые приносят основную массу денег. За ними нужно следить в первую очередь: никогда не допускать их дефицита на складе и обеспечивать приоритетными закупками сырья.</li><li><strong>Группа С (Аутсайдеры):</strong> Товары, занимающие микро-доли в диаграмме. Стоит задуматься: возможно, они «замораживают» ваши деньги в виде специфического сырья на складе и отнимают время, не принося ощутимого результата.</li></ul><hr><h2 id="🧠-синергия-метрик-как-принимать-решения" tabindex="-1">🧠 Синергия метрик: Как принимать решения <a class="header-anchor" href="#🧠-синергия-метрик-как-принимать-решения" aria-label="Permalink to &quot;🧠 Синергия метрик: Как принимать решения&quot;">​</a></h2><p>Настоящая сила вкладки «Аналитика» раскрывается при совместном чтении показателей:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ситуация на графиках</th><th style="text-align:left;">Диагноз бизнеса</th><th style="text-align:left;">Рекомендуемое действие</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Time ROI низкий</strong>, но <strong>Средний чек высокий</strong></td><td style="text-align:left;">Вы продаете дорогие, но очень трудоемкие вещи. Вы работаете на износ.</td><td style="text-align:left;">Повысить цены в Калькуляторе или упростить конструкцию изделий.</td></tr><tr><td style="text-align:left;"><strong>Точка безубыточности растет</strong> из месяца в месяц</td><td style="text-align:left;">Ваши постоянные расходы (аренда, подписки, реклама) съедают маржу.</td><td style="text-align:left;">Провести аудит в ДДС и сократить необязательные операционные траты.</td></tr><tr><td style="text-align:left;"><strong>Структура выручки</strong> показывает доминирование одного товара</td><td style="text-align:left;">Бизнес не диверсифицирован. Вы зависите от одного «хита».</td><td style="text-align:left;">Запустить маркетинговые акции на товары из категории «Прочие», чтобы распределить риски.</td></tr></tbody></table>',30)])])}const u=e(o,[["render",n]]);export{h as __pageData,u as default};
